using System.Data;using Backend.BDFolder;using Backend.Exceptions;using Backend.Helpers;using Backend.Models;using Backend.Policies;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;using Polly;namespace Backend.Services;public class PuestoService{    private readonly IDbContextFactory<TransportesRojasDbContext> _factory;    private readonly ILogger<PuestoService> _logger;    private readonly ResiliencePipeline _pipeline;    public PuestoService(        IDbContextFactory<TransportesRojasDbContext> factory,        ILogger<PuestoService> logger)    {        _factory = factory;        _logger = logger;        _pipeline = PollyPolicies.CrearPipelineSerializacion(logger);    }    public async Task<List<PuestoResponse>> GetPuestosAsync(int skip = 0, int take = 100)    {        await using var ctx = await _factory.CreateDbContextAsync();        return await ctx.Puestos            .AsNoTracking()            .OrderBy(p => p.Id)            .Skip(skip)            .Take(take)            .Select(p => new PuestoResponse(p.Id, p.Nombre, p.Descripcion))            .ToListAsync();    }    public async Task<PuestoResponse?> GetPuestoByIdAsync(long id)    {        await using var ctx = await _factory.CreateDbContextAsync();        var puesto = await ctx.Puestos            .AsNoTracking()            .FirstOrDefaultAsync(p => p.Id == id);        return puesto is null            ? null            : new PuestoResponse(puesto.Id, puesto.Nombre, puesto.Descripcion);    }    public async Task<PuestoResponse> CreatePuestoAsync(CrearPuestoModel model)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var existeNombre = await ctx.Puestos                    .AnyAsync(p => p.Nombre == model.Nombre, ct);                if (existeNombre)                    throw new InvalidOperationException(                        $"Ya existe un puesto con el nombre '{model.Nombre}'.");                var nuevo = new Puesto                {                    Nombre = model.Nombre,                    Descripcion = model.Descripcion                };                ctx.Puestos.Add(nuevo);                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Puesto creado. Id={Id}, Nombre='{Nombre}'",                    nuevo.Id, nuevo.Nombre);                return new PuestoResponse(nuevo.Id, nuevo.Nombre, nuevo.Descripcion);            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al crear puesto.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    public async Task<bool> UpdatePuestoAsync(long id, ActualizarPuestoModel model)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var puesto = await ctx.Puestos.FindAsync(new object[] { id }, ct);                if (puesto is null) return false;                var existeNombre = await ctx.Puestos                    .AnyAsync(p => p.Nombre == model.Nombre && p.Id != id, ct);                if (existeNombre)                    throw new InvalidOperationException(                        $"Ya existe otro puesto con el nombre '{model.Nombre}'.");                puesto.Nombre = model.Nombre;                puesto.Descripcion = model.Descripcion;                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Puesto actualizado. Id={Id}", id);                return true;            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al actualizar puesto.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    public async Task<bool> DeletePuestoAsync(long id)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var puesto = await ctx.Puestos.FindAsync(new object[] { id }, ct);                if (puesto is null) return false;                var estaEnUso = await ctx.EmpleadosPuestosHistorial                    .AnyAsync(ep => ep.PuestoId == id, ct);                if (estaEnUso)                    throw new InvalidOperationException(                        "No se puede eliminar el puesto porque está asignado a uno o más empleados.");                ctx.Puestos.Remove(puesto);                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Puesto eliminado. Id={Id}", id);                return true;            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al eliminar puesto.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    private async Task RollbackSafeAsync(        Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction tx)    {        try { await tx.RollbackAsync(); }        catch (Exception rollbackEx)        {            _logger.LogWarning(rollbackEx, "Error durante rollback (puede ser esperado).");        }    }}